contracts/gauge/interfaces/ICLGauge.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity =0.7.6;

import {ICLPool} from 'contracts/gauge/interfaces/ICLPool.sol';
import {IGauge} from 'contracts/gauge/interfaces/IGauge.sol';
import {INonfungiblePositionManager} from 'contracts/gauge/interfaces/INonfungiblePositionManager.sol';

interface ICLGauge is IGauge {
  /**
   * @notice Emitted when a position is deposited into the gauge.
   * @param _caller The address that deposited the position.
   * @param _user The address credited as the staked owner.
   * @param _tokenId The tokenId of the deposited position.
   * @param _liquidityToStake The amount of liquidity staked in the pool.
   */
  event Deposit(address indexed _caller, address indexed _user, uint256 indexed _tokenId, uint128 _liquidityToStake);

  /**
   * @notice Emitted when a position is withdrawn from the gauge.
   * @param _caller The address that withdrew the position.
   * @param _user The address whose stake was withdrawn.
   * @param _tokenId The tokenId of the withdrawn position.
   * @param _liquidityToStake The amount of liquidity unstaked from the pool.
   */
  event Withdraw(address indexed _caller, address indexed _user, uint256 indexed _tokenId, uint128 _liquidityToStake);

  /**
   * @notice Emitted when accrued emissions are claimed for a staked position.
   * @param _account The address of the LP staker whose emissions were claimed.
   * @param _tokenId The tokenId of the staked position.
   * @param _recipient The recipient of the claimed emissions.
   * @param _rewardAmount The amount of emissions paid to the recipient.
   */
  event EmissionsClaimed(
    address indexed _account, uint256 indexed _tokenId, address indexed _recipient, uint256 _rewardAmount
  );

  /**
   * @notice Emitted when accrued emissions are stored instead of claimed during withdrawal.
   * @param _account The address of the LP staker credited with the deferred emissions.
   * @param _tokenId The tokenId whose emissions were stored.
   * @param _rewardAmount The post-penalty, post-referral emissions added to the account's deferred balance.
   */
  event EmissionsDeferred(address indexed _account, uint256 indexed _tokenId, uint256 _rewardAmount);

  /**
   * @notice Emitted when a position's referral emissions are stored for a later claim.
   * @param _account The address of the LP staker whose emissions paid the referral.
   * @param _tokenId The tokenId of the staked position.
   * @param _referral The referral address credited with the emissions.
   * @param _amount The referral emissions added to the referral's deferred balance.
   */
  event ReferralEmissionsDeferred(
    address indexed _account, uint256 indexed _tokenId, address indexed _referral, uint256 _amount
  );

  /**
   * @notice Emitted when an account's deferred emissions are claimed.
   * @param _account The account whose deferred emissions were claimed.
   * @param _recipient The recipient of the claimed emissions.
   * @param _amount The deferred emissions paid to the recipient after referral.
   */
  event DeferredEmissionsClaimed(address indexed _account, address indexed _recipient, uint256 _amount);

  /**
   * @notice Emitted when an early withdrawal penalty is applied to a position's accrued emissions.
   * @param _from The address of the LP staker whose emissions were penalized.
   * @param _tokenId The tokenId of the staked position.
   * @param _penalty The amount of emissions forfeited as the penalty.
   */
  event EarlyWithdrawPenalty(address indexed _from, uint256 indexed _tokenId, uint256 _penalty);

  /**
   * @notice Emitted when a per-tokenId withdrawal approval is set or cleared
   * @param _owner The position owner
   * @param _operator The approved operator (address(0) if cleared)
   * @param _tokenId The approved token ID
   */
  event Approval(address indexed _owner, address indexed _operator, uint256 indexed _tokenId);

  /**
   * @notice Emitted when the gauge settles emissions accrued in the LeafVoter
   * @dev Not emitted when a settlement accrues no new emissions
   * @param _cumulativeRewardShare The LeafVoter's cumulative reward share at this settlement
   * @param _delta The emissions accrued since the previous settlement
   */
  event GaugeSettled(uint256 _cumulativeRewardShare, uint256 _delta);

  /**
   * @notice Called on gauge creation by CLGaugeFactory
   * @dev Only callable by the gauge factory
   * @param _pool The address of the pool
   * @param _votingRewardsManager The address of the voting rewards manager contract
   * @param _token0 The address of token0 of the pool
   * @param _token1 The address of token1 of the pool
   * @param _tickSpacing The tick spacing of the pool
   * @param _isPool Whether the attached pool is a real pool or not
   */
  function initialize(
    address _pool,
    address _votingRewardsManager,
    address _token0,
    address _token1,
    int24 _tickSpacing,
    bool _isPool
  ) external;

  /**
   * @notice Settle the gauge in the LeafVoter and return the emissions accrued since the last settlement
   * @dev Only callable by the corresponding pool
   * @dev Pulls the gauge's cumulative reward share from the LeafVoter and advances the gauge's cursor
   * @dev Reports the settle to the gauge tape through the factory: a full report when the cursor
   *      advances, a refresh when it holds at a nonzero level, nothing on a regression
   * @return _delta The emissions accrued since the gauge's last settlement
   */
  function settleGauge() external returns (uint256 _delta);

  /**
   * @notice Settle the pool and forfeit any accumulated rollover back to the LeafVoter
   * @dev Permissionless. Emissions accrued while no staked liquidity is in range are banked in the
   *      pool as rollover and normally forfeited during claims; an idle gauge with no staked
   *      positions has no claims, so this entrypoint returns them to the voter directly.
   */
  function forfeitRollover() external;

  /**
   * @notice Claim the LP's accrued emissions across the given positions
   * @dev Also claims all account-level deferred LP emissions regardless of the requested positions
   * @param _account The address of the LP staker whose emissions are being claimed
   * @param _recipient The recipient of the claimed emissions
   * @param _tokenIds The staked positions to claim
   */
  function claimEmissions(address _account, address _recipient, uint256[] calldata _tokenIds) external;

  /**
   * @notice NonfungiblePositionManager used to create nfts accepted by this gauge.
   * @return The address of the NonfungiblePositionManager.
   */
  function nft() external view returns (INonfungiblePositionManager);

  /**
   * @notice Address of the CL pool linked to the gauge.
   * @return The address of the CL pool.
   */
  function pool() external view returns (ICLPool);

  /**
   * @notice Cached address of token0, corresponding to token0 of the pool.
   * @return The address of token0.
   */
  function token0() external view returns (address);

  /**
   * @notice Cached address of token1, corresponding to token1 of the pool.
   * @return The address of token1.
   */
  function token1() external view returns (address);

  /**
   * @notice Cached tick spacing of the pool.
   * @return The tick spacing of the pool.
   */
  function tickSpacing() external view returns (int24);

  /**
   * @notice Returns the rewardGrowthInside of the position at the last user action (deposit, withdraw, claimEmissions)
   * @param _tokenId The tokenId of the position
   * @return The rewardGrowthInside for the position
   */
  function rewardGrowthInside(uint256 _tokenId) external view returns (uint256);

  /**
   * @notice Returns the block number at which a position was deposited
   * @param _tokenId The tokenId of the position
   * @return The deposit block for the position
   */
  function depositBlock(uint256 _tokenId) external view returns (uint256);

  /**
   * @notice Returns net LP emissions stored for an account when emission minting fails during withdrawal
   * @param _account The account credited with the deferred emissions
   * @return The post-penalty, post-referral deferred LP emissions
   */
  function deferredEmissions(address _account) external view returns (uint256);

  /**
   * @notice Estimates the claimable emissions for a given account across the requested positions
   * @dev Assumes _tokenIds contains no duplicates
   * @dev Rewards accrued since the last settlement are an estimate
   * @dev Includes the account-level deferred LP emissions
   * @param _account The address of the LP staker
   * @param _tokenIds The staked positions
   * @return The estimated claimable amount
   */
  function earned(address _account, uint256[] memory _tokenIds) external view returns (uint256);

  /**
   * @notice Returns the operator approved to withdraw a specific staked position
   * @param _tokenId The staked NFT token ID
   * @return The approved operator, or address(0) if none
   */
  function getApproved(uint256 _tokenId) external view returns (address);

  /**
   * @notice Fetch all tokenIds staked by a given account
   * @param _depositor The address of the user
   * @return The tokenIds of the staked positions
   */
  function stakedValues(address _depositor) external view returns (uint256[] memory);

  /**
   * @notice Fetch a staked tokenId by index
   * @param _depositor The address of the user
   * @param _index The index of the staked tokenId
   * @return The tokenId of the staked position
   */
  function stakedByIndex(address _depositor, uint256 _index) external view returns (uint256);

  /**
   * @notice Check whether a position is staked in the gauge by a certain user
   * @param _depositor The address of the user
   * @param _tokenId The tokenId of the position
   * @return Whether the position is staked in the gauge
   */
  function stakedContains(address _depositor, uint256 _tokenId) external view returns (bool);

  /**
   * @notice The amount of positions staked in the gauge by a certain user
   * @param _depositor The address of the user
   * @return The amount of positions staked in the gauge
   */
  function stakedLength(address _depositor) external view returns (uint256);
}

contracts/gauge/interfaces/ICLGaugeFacto.content:
// SPDX-License-Identifier: MIT
pragma solidity >=0.7.6;
pragma abicoder v2;

import {ICLGaugeTape} from 'contracts/gauge/interfaces/tape/ICLGaugeTape.sol';

interface ICLGaugeFactory {
  struct ReferralConfig {
    address referral;
    uint256 share;
  }

  struct PenaltyConfig {
    uint256 minStakeBlocks;
    uint256 penaltyRate;
  }

  event GaugeCreated(address indexed _gauge, address indexed _pool, bool _isPool);
  event EmissionCapSet(address indexed _gauge, uint128 _cap, address indexed _caller);
  event FeeFlushFailed(address indexed _gauge);
  event DefaultCapSet(uint128 _cap);
  event OperatorCapRangeSet(uint128 _minCap, uint128 _maxCap);
  event MaxShareCapSet(uint256 _cap);
  event ReferralConfigSet(address indexed _gauge, address indexed _referral, uint256 _share);
  event PenaltyConfigSet(uint256 _minStakeBlocks, uint256 _penaltyRate);
  event MinStakeBlocksSet(address indexed _gauge, uint256 _minStakeBlocks);

  /// @notice Emitted when the gauge tape the gauges record on is set or cleared
  /// @param _clGaugeTape The tape address after the change. The zero address disables recording
  /// @param _gasLimit The gas budget of each relayed record call
  event ClGaugeTapeSet(address indexed _clGaugeTape, uint32 _gasLimit);

  /// @notice PIPS denominator (1_000_000 = 100%).
  function MAX_PIPS() external view returns (uint256);

  /// @notice Initial factory-wide max referral share cap.
  function DEFAULT_MAX_SHARE_CAP() external view returns (uint256);

  /// @notice Initial factory-wide minimum-stake threshold in blocks.
  function DEFAULT_MIN_STAKE_BLOCKS() external view returns (uint256);

  /// @notice Initial factory-wide penalty rate in PIPS.
  function DEFAULT_PENALTY_RATE() external view returns (uint256);

  /// @notice Address of the LeafVoter contract.
  function leafVoter() external view returns (address);

  /// @notice GaugeManager authorized to call `createGauge`.
  function gaugeManager() external view returns (address);

  /// @notice VotingRewardsFactory deploying each gauge's VotingRewardsManager.
  function votingRewardsFactory() external view returns (address);

  /// @notice Short string label identifying this factory's gauge type.
  function GAUGE_TYPE() external view returns (string memory);

  /// @notice Address of the gauge implementation contract
  function implementation() external view returns (address);

  /// @notice Address of the NonfungiblePositionManager used to create nfts that gauges will accept
  function nft() external view returns (address);

  /// @notice Upper bound on minStakeBlocks, set at construction.
  function maxMinStakeBlocks() external view returns (uint256);

  function CAP_ADMIN_ROLE() external view returns (bytes32);

  function REFERRAL_ADMIN_ROLE() external view returns (bytes32);

  function PENALTY_ADMIN_ROLE() external view returns (bytes32);

  function CAP_OPERATOR_ROLE() external view returns (bytes32);

  /// @notice Administers `GAUGE_TAPE_MANAGER_ROLE` and itself: grants and revokes the gauge tape managers.
  function GAUGE_TAPE_MANAGER_ADMIN_ROLE() external view returns (bytes32);

  /// @notice Sets and clears the gauge tape the gauges record on, through `setClGaugeTape`.
  function GAUGE_TAPE_MANAGER_ROLE() external view returns (bytes32);

  /// @notice True if this factory deployed `gauge`.
  function isGauge(address _gauge) external view returns (bool);

  /// @notice Emission cap stored for `gauge`.
  function emissionCap(address _gauge) external view returns (uint128);

  /// @notice Factory-wide default emission cap.
  function defaultCap() external view returns (uint128);

  /// @notice Set the default emission cap for future gauges.
  /// @dev Existing gauges retain their stored emission caps.
  function setDefaultCap(uint128 _cap) external;

  /// @notice Set a per-gauge emission cap.
  function setEmissionCap(address _gauge, uint128 _cap) external;

  /**
   * @notice Sets per-gauge emission caps in a single call.
   * @dev Applies the `setEmissionCap` rules to each entry. Reverts if any entry fails.
   * @param _gauges Addresses of the gauges to update.
   * @param _caps Emission caps, matched to `_gauges` by index.
   */
  function setEmissionCaps(address[] calldata _gauges, uint128[] calldata _caps) external;

  /**
   * @notice Sets a gauge's emission cap to zero without requiring a successful fee flush.
   * @dev Only callable by the emergency council.
   * @param _gauge Address of the gauge to deactivate.
   */
  function clearEmissionCap(address _gauge) external;

  /// @notice Minimum cap CAP_OPERATOR_ROLE may set.
  function operatorMinCap() external view returns (uint128);

  /// @notice Maximum cap CAP_OPERATOR_ROLE may set.
  function operatorMaxCap() external view returns (uint128);

  /// @notice Set operator cap range.
  function setOperatorCapRange(uint128 _minCap, uint128 _maxCap) external;

  /// @notice Factory-wide maximum referral share cap.
  function maxShareCap() external view returns (uint256);

  /// @notice Set factory-wide maximum referral share cap.
  function setMaxShareCap(uint256 _cap) external;

  /// @notice Returns (address(0), 0) when unconfigured.
  function referralConfig(address _gauge) external view returns (address _referral, uint256 _share);

  /// @notice Set or clear referral config.
  function setReferralConfig(address _gauge, address _referral, uint256 _share) external;

  /// @notice Factory-wide penalty config.
  function penaltyConfig() external view returns (PenaltyConfig memory);

  /**
   * @notice Effective penalty config for `_gauge`.
   * @param _gauge The gauge to query.
   * @return The penalty config with the effective minimum-stake threshold.
   */
  function effectivePenaltyConfig(address _gauge) external view returns (PenaltyConfig memory);

  /// @notice Effective minimum-stake threshold for `gauge`, in blocks.
  function minStakeBlocks(address _gauge) external view returns (uint256);

  /// @notice Set factory-wide penalty config.
  function setPenaltyConfig(uint256 _minStakeBlocks, uint256 _penaltyRate) external;

  /// @notice Set or clear per-gauge minimum-stake block override.
  function setMinStakeBlocks(address _gauge, uint256 _minStakeBlocks) external;

  /// @notice The gauge tape the gauges record on. The zero address means recording is disabled
  function clGaugeTape() external view returns (address);

  /// @notice The gas budget of each relayed record call
  function clGaugeTapeGasLimit() external view returns (uint32);

  /**
   * @notice Sets or clears the gauge tape the gauges record on
   * @dev Must be called by a `GAUGE_TAPE_MANAGER_ROLE` holder; `GAUGE_TAPE_MANAGER_ADMIN_ROLE` alone does not
   *      qualify, it only decides who holds the manager role. The zero address disables recording. A zero gas
   *      limit reverts. The limit itself is not bounded, the audited pattern the pool factory relays share, so it is the manager's to get
   *      right. Too low, and the capped record call runs out of gas and the write is skipped until the
   *      manager raises it. Too high, near a block's gas limit, and the relay's guard refuses every settle;
   *      since the gauges settle on every stake, withdraw, claim and tick-crossing swap, that blocks every
   *      gauge action, withdrawals included, until the manager lowers it. The pool tape has no such
   *      exposure since its relay sits on the swap path alone
   * @param _clGaugeTape The new gauge tape address
   * @param _gasLimit The gas budget of each relayed record call
   */
  function setClGaugeTape(address _clGaugeTape, uint32 _gasLimit) external;

  /**
   * @notice Relays a gauge's settle report to the gauge tape inside a gas-capped call
   * @dev Returns silently when no tape is set or the caller is not a gauge of this factory. The tape
   *      call runs with `clGaugeTapeGasLimit` gas and its result is ignored, so a reverting tape is a
   *      no-op for the caller. Reverts with `GL` when the gas left is not above the budget, the guard the
   *      pool factory relays share; this closes the starvation path where a caller funds the settle but
   *      not the capped subcall. EIP-150 forwards `min(budget, gasleft() - gasleft() / 64)`, so a caller
   *      sitting just above the guard can still hand the tape slightly less than its budget
   * @param _data The gauge's settle report
   */
  function recordClGaugeTape(ICLGaugeTape.GaugeTapeData calldata _data) external;

  /**
   * @notice Predicts the deterministic gauge address for `_pool`.
   * @dev The salt derives from the pool address, so the prediction is fixed
   *      and unique per pool. The registry links at most one gauge per
   *      target, so no second deployment ever needs a fresh address.
   * @param _pool The address of the pool.
   * @return _gauge Predicted gauge address.
   */
  function computeGaugeAddress(address _pool) external view returns (address _gauge);

  /**
   * @notice Called by the GaugeManager to deploy and initialize a CL gauge
   *         together with its VotingRewardsManager.
   * @dev The gauge is deployed and registered before the VotingRewardsManager
   *      is created through the VotingRewardsFactory, seeded with the pool's
   *      pair tokens as the initial reward tokens.
   * @param _target The address of the pool the gauge points at.
   * @param _factoryData Optional factory params. First byte 0x01 encodes a 65-byte referral config.
   * @return _gauge The address of the created gauge
   * @return _rewards The address of the deployed VotingRewardsManager
   */
  function createGauge(address _target, bytes calldata _factoryData) external returns (address _gauge, address _rewards);
}

contracts/gauge/interfaces/ICLPool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity =0.7.6;

/// @title Minimal CLPool interface
/// @notice Used to support the integration with the core implementation
/// @dev For full context, please review the Uniswap implementation under GPL license.
interface ICLPool {
  function token0() external view returns (address);

  function token1() external view returns (address);

  function tickSpacing() external view returns (int24);

  /// @notice The reward growth as a Q128.128 rewards of emission collected per unit of liquidity for the entire life of the pool
  /// @dev This value can overflow the uint256
  function rewardGrowthGlobalX128() external view returns (uint256);

  /// @notice The currently in range staked liquidity available to the pool
  /// @dev This value has no relationship to the total staked liquidity across all ticks
  function stakedLiquidity() external view returns (uint128);

  /// @notice The amounts of token0 and token1 that are owed to the gauge
  /// @dev Gauge fees will never exceed uint128 max in either token
  function gaugeFees() external view returns (uint128 amount0, uint128 amount1);

  /// @notice Returns data about reward growth within a tick range.
  /// RewardGrowthGlobalX128 can be supplied as a parameter for claimable reward calculations.
  /// @dev Used in gauge reward/earned calculations
  /// @param tickLower The lower tick of the range
  /// @param tickUpper The upper tick of the range
  /// @param _rewardGrowthGlobalX128 a calculated rewardGrowthGlobalX128 or 0 (in case of 0 it means we use the rewardGrowthGlobalX128 from state)
  /// @return rewardGrowthInsideX128 The reward growth in the range
  function getRewardGrowthInside(
    int24 tickLower,
    int24 tickUpper,
    uint256 _rewardGrowthGlobalX128
  ) external view returns (uint256 rewardGrowthInsideX128);

  /// @notice Initialize gauge and nft manager
  /// @dev Callable only once, by the gauge factory
  /// @param _gauge The gauge corresponding to this pool
  /// @param _nft The position manager used for position management
  function setGaugeAndPositionManager(address _gauge, address _nft) external;

  /// @notice Convert existing liquidity into staked liquidity
  /// @notice Only callable by the gauge associated with this pool
  /// @param stakedLiquidityDelta The amount by which to increase or decrease the staked liquidity
  /// @param tickLower The lower tick of the position for which to stake liquidity
  /// @param tickUpper The upper tick of the position for which to stake liquidity
  function stake(int128 stakedLiquidityDelta, int24 tickLower, int24 tickUpper) external;

  /// @notice Settle the pool's reward growth to the current block timestamp and return the accrued rollover
  /// @return _rollover Emissions accrued while no staked liquidity was in range. Reset to 0 after this call.
  function settleToBlock() external returns (uint256 _rollover);

  /// @notice Collect the gauge fee accrued to the pool
  /// @param recipient The address that receives the claimed gauge fees
  /// @return amount0 The gauge fee collected in token0
  /// @return amount1 The gauge fee collected in token1
  function collectFees(address recipient) external returns (uint128 amount0, uint128 amount1);
}

contracts/gauge/interfaces/IGauge.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity =0.7.6;

interface IGauge {
  /**
   * @notice Emitted when the gauge collects pool fees through the VotingRewardsManager.
   * @param _caller The address that triggered fee collection.
   * @param _claimed0 The amount of token0 fees collected.
   * @param _claimed1 The amount of token1 fees collected.
   */
  event ClaimFees(address indexed _caller, uint256 _claimed0, uint256 _claimed1);

  /**
   * @notice Emitted when an account grants or revokes claim approval for an operator
   * @param _account The account whose approval state changed
   * @param _operator The operator being approved or revoked
   * @param _approved The new approval state
   */
  event ClaimApproval(address indexed _account, address indexed _operator, bool _approved);

  /**
   * @notice Emitted when an owner grants or revokes blanket withdrawal approval for an operator
   * @param _owner The owner whose approval changed
   * @param _operator The operator being approved or revoked
   * @param _approved The new approval state
   */
  event ApprovalForAll(address indexed _owner, address indexed _operator, bool _approved);

  /**
   * @notice Emitted when a referral's deferred emissions are claimed.
   * @param _referral The referral address whose deferred emissions were claimed.
   * @param _recipient The recipient of the claimed emissions.
   * @param _amount The deferred referral emissions paid to the recipient.
   */
  event ReferralEmissionsClaimed(address indexed _referral, address indexed _recipient, uint256 _amount);

  /**
   * @notice Deposit a staked position
   * @param _lp A token amount for V2 gauges or an NFT token ID for CL gauges
   */
  function deposit(uint256 _lp) external;

  /**
   * @notice Deposit a staked position on behalf of an owner
   * @dev For V2 gauges, approved MetaRouters are trusted to restrict `_owner` to the account that authorized the
   *      routed deposit; otherwise, they could reset another account's early-unstake penalty timer.
   * @param _lp A token amount for V2 gauges or an NFT token ID for CL gauges
   * @param _owner The address credited as the staked owner
   */
  function depositFor(uint256 _lp, address _owner) external;

  /**
   * @notice Withdraw a staked position owned by the caller
   * @param _lp A token amount for V2 gauges or an NFT token ID for CL gauges
   */
  function withdraw(uint256 _lp) external;

  /**
   * @notice Withdraw a staked position on behalf of an account
   * @param _lp A token amount for V2 gauges or an NFT token ID for CL gauges
   * @param _account The position owner
   */
  function withdrawFrom(uint256 _lp, address _account) external;

  /**
   * @notice Claim accrued emissions
   * @dev Requires the caller to be the LP or an operator with claim approval
   * @dev For CL gauges, the account-wide claim also includes account-level deferred LP emissions
   * @param _account The address of the LP staker whose emissions are being claimed
   * @param _recipient The recipient of the claimed emissions
   */
  function claimEmissions(address _account, address _recipient) external;

  /**
   * @notice Claims a referral's deferred emissions.
   * @dev Requires the caller to be the referral or an operator with claim approval.
   * @dev Contract referrals must be able to call this function or approve an operator to call it on their behalf.
   * @param _referral The referral address whose deferred emissions are being claimed.
   * @param _recipient The recipient of the claimed emissions.
   */
  function claimReferralEmissions(address _referral, address _recipient) external;

  /**
   * @notice Grant or revoke an operator's approval to claim emissions on behalf of the caller
   * @param _operator The operator to approve or revoke
   * @param _approved True to approve, false to revoke
   */
  function approveForClaim(address _operator, bool _approved) external;

  /**
   * @notice Grant or revoke blanket withdrawal authorization for an operator over all staked positions
   * @param _operator The operator to authorize or revoke
   * @param _approved True to grant blanket approval, false to revoke
   */
  function setApprovalForAll(address _operator, bool _approved) external;

  /**
   * @notice Approve an operator to withdraw a staked position
   * @param _operator The operator to authorize
   * @param _lp A token amount for V2 gauges or an NFT token ID for CL gauges
   */
  function approve(address _operator, uint256 _lp) external;

  /**
   * @notice Collect currently claimable pool fees directly to the VotingRewardsManager.
   * @dev Only callable by the VotingRewardsManager.
   * @return _amount0 The token0 fees collected.
   * @return _amount1 The token1 fees collected.
   */
  function collectFees() external returns (uint256 _amount0, uint256 _amount1);

  /**
   * @notice LeafVoter contract used for gauge settlement.
   * @return The address of the LeafVoter.
   */
  function voter() external view returns (address);

  /**
   * @notice Address of the factory that created this gauge.
   * @return The address of the gauge factory.
   */
  function gaugeFactory() external view returns (address);

  /**
   * @notice Address of the VotingRewardsManager contract linked to the gauge.
   * @return The address of the VotingRewardsManager.
   */
  function votingRewardsManager() external view returns (address);

  /**
   * @notice Returns if gauge is linked to a legitimate pool.
   * @return Whether the gauge is linked to a legitimate pool.
   */
  function isPool() external view returns (bool);

  /**
   * @notice The gauge's cursor into the LeafVoter's cumulative reward share accumulator
   * @return The cumulative reward share at the gauge's last settlement
   */
  function lastCumulativeRewardShare() external view returns (uint256);

  /**
   * @notice Estimates the claimable emissions for a given account
   * @dev Rewards accrued since the last settlement are an estimate
   * @dev For CL gauges, includes the account's net deferred LP emissions
   * @param _account The address of the LP staker
   * @return The estimated claimable amount
   */
  function earned(address _account) external view returns (uint256);

  /**
   * @notice Whether an operator is approved to claim emissions on behalf of an account
   * @param _account The account that granted the approval
   * @param _operator The operator being queried
   * @return True if the operator is approved
   */
  function approvedForClaim(address _account, address _operator) external view returns (bool);

  /**
   * @notice Returns deferred emissions stored for a referral address
   * @param _referral The referral address credited with the emissions
   * @return The deferred referral emissions
   */
  function deferredReferralEmissions(address _referral) external view returns (uint256);

  /**
   * @notice Returns whether an operator has blanket withdrawal authorization for an owner's positions
   * @param _owner The staked position owner
   * @param _operator The candidate operator
   * @return True if blanket approval is active
   */
  function isApprovedForAll(address _owner, address _operator) external view returns (bool);

  /**
   * @notice Return currently claimable pool fees without moving tokens or mutating state.
   * @return _amount0 The currently pending token0 fees.
   * @return _amount1 The currently pending token1 fees.
   */
  function pendingFees() external view returns (uint256 _amount0, uint256 _amount1);
}

